    \newcommand{\ENDLOOP}{\end{ALC@loop}\ALC@it\algorithmicendloop}
    \newcommand{\ENDFUNCTION}{\end{ALC@func}\ALC@it\algorithmicendfunction}
    \newcommand{\ENDMAIN}{\end{ALC@main}\ALC@it\algorithmicendmain}
  } 
  \renewcommand{\@toodeep}{}
