%     \begin{algorithmic}
%         \STATE \textbf{Input:} point $x_0 \in \R^d$, stepsizes $\gamma_k \geq 0$
%         % \STATE Each worker $i \in [m]$ computes the stochastic gradient at $x_0$ in parallel
%         \STATE All $n$ workers start computing stochastic gradient at $x_0$ 
%         \FOR{$k = 0, \dots, K - 1$}
%             \STATE Gradient $\nabla f(x^{k-\delta^k}; \xi^{k-\delta^k})$ arrives from worker $i$
%             \STATE Update: $x^{k+1} = x^{k} - \gamma_k \nabla f(x^{k-\delta^k}; \xi^{k-\delta^k})$
%             \STATE Worker $i$ begins calculating $\nabla f\(x^{k+1}; \xi^{k+1}\)$
%         \ENDFOR
%     \end{algorithmic}
% \end{algorithm}
\begin{algorithm}[H]
    \caption{\algname{Asynchronous SGD}}
    \label{alg:asgd}
    \begin{algorithmic}
        \STATE \textbf{Input:} point $x^0 \in \R^d$, stepsizes $\gamma_k \geq 0$
        % \STATE Each worker $i \in [m]$ computes the stochastic gradient at $x_0$ in parallel
        % \STATE All $n$ workers start computing stochastic gradient at $x_0$ with $k = 0$
        % \STATE Workers start computing stoch. gradient at $x^k$ with $k = 0$
        % \FOR{$k = 0, \dots, K - 1$}
        \STATE Set $k = 0$
        \STATE Workers start computing stochastic gradients at $x^0$
        \WHILE{True}
            \STATE Gradient $\nabla f(x^{k-\delta^k}; \xi^{k-\delta^k}_{i})$ arrives from worker $i$
            \STATE Update: $x^{k+1} = x^{k} - \gamma_k \nabla f(x^{k-\delta^k}; \xi^{k-\delta^k}_{i})$
            \STATE Worker $i$ begins calculating $\nabla f(x^{k+1}; \xi^{k+1}_{i})$
            \STATE Update the iteration number $k = k + 1$
        \ENDWHILE
    \end{algorithmic}
\end{algorithm}
This is a greedy and asynchronous method. 
Once a worker finishes computation of the stochastic gradient, it immediately sends the gradient to the server, which updates the current iterate without waiting for other workers.
Notice that, unlike vanilla \algname{SGD}, the update is performed using the stochastic gradient calculated at the point $x^{k-\delta^k}$, where the index $k-\delta^k$ corresponds to the iteration when the worker started computing the gradient, which can be significantly outdated.
The sequence $\{\delta^k\}$ is a sequence of delays of \algname{Asynchronous SGD}, where $\delta^k \geq 0$ is defined as the difference between the iteration when worker $i$ started computing the gradient and iteration $k$, when it was applied.

\algname{Asynchronous SGD} methods have a long history, originating in 1986 \citep{tsitsiklis1986distributed} and regaining prominence with the seminal work of \citet{recht2011hogwild}.
The core idea behind \algname{Asynchronous SGD} is simple: to achieve fast convergence, all available resources are utilized by keeping all workers busy at all times.
This principle has been validated in numerous studies, showing that \algname{Asynchronous SGD} can outperform naive synchronous \algname{SGD} methods \citep{feyzmahdavian2016asynchronous,dutta2018slow,nguyen2018sgd,arjevani2020tight,cohen2021asynchronous,mishchenko2022asynchronous,koloskova2022sharper,islamov2023asgrad,feyzmahdavian2023asynchronous}.

\subsection{Assumptions}
\label{sec:assumption}

In this paper, we consider the standard assumptions from the nonconvex world.
\begin{assumption}
    \label{ass:lipschitz_constant}
    Function $f$ is differentiable, and its gradient is $L$--Lipschitz continuous, i.e., 
    $$
    \norm{\nabla f(x) - \nabla f(y)} \leq L \norm{x - y}, \; \forall x, y \in \R^d.
    $$
 \end{assumption}

 \begin{assumption}
    \label{ass:lower_bound}
    There exist $f^{\inf} \in \R$ such that $f(x) \geq f^{\inf}$ for all $x \in \R^d$. 
    We define $\Delta \eqdef f(x^0) - f^{\inf},$ where $x^0$ is the starting point of optimization methods.
 \end{assumption}

\begin{assumption}
    \label{ass:stochastic_variance_bounded}
    The stochastic gradients $\nabla f(x; \xi)$ are unbiased and have bounded variance $\sigma^2\geq0$.  
    Specifically,  
    \begin{gather*}
         \ExpSub{\xi}{\nabla f(x;\xi)} = \nabla f(x), \; \forall x \in \R^d,\\
         \ExpSub{\xi}{\sqnorm{\nabla f(x;\xi) - \nabla f(x)}} \leq \sigma^2,\; \forall x \in \R^d.
    \end{gather*} 
\end{assumption} 

