\section{Proof of \Cref{lem:time_R}}
\label{proof:time_R}

\begin{restate-lemma}{\ref{lem:time_R}}
    Let workers' computation times satisfy the \emph{fixed computation model} (\eqref{eq:worker-time} and \eqref{eq:sorted_t_i}).
    Let $R$ be the delay threshold of \Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}.
    The time required to complete any $R$ consecutive iterates updates of \Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops} is at most
    \begin{equation}
        \tag{\ref{eq:time_R}}
        t(R) \eqdef 2 \min\limits_{m \in [n]} \left[\left(\frac{1}{m} \sum\limits_{i=1}^m \frac{1}{\tau_i}\right)^{-1} \left( 1 + \frac{R}{m} \right)\right].
    \end{equation}
\end{restate-lemma}

\begin{proof}
    We now focus on \Cref{alg:ringmasternewstops}.
    Let us consider a simplified notation of $t(R)$:
    \begin{align*}
        t \eqdef t(R) = 2 \min_{m\in[n]} \left(\left(\sum_{i=1}^m \frac{1}{\tau_i}\right)^{-1} (R + m)\right) = 2 \min\limits_{m \in [n]} \left(\frac{1}{m} \sum\limits_{i=1}^m \frac{1}{\tau_i}\right)^{-1} \left( 1 + \frac{R}{m} \right).
    \end{align*}
    Let us fix any iteration $k$, and consider the consecutive iterations from $k$ to $k + R - 1$.
    By the design of \Cref{alg:ringmasternewstops}, any worker will be stopped at most one time, meaning that at most one stochastic gradient will be ignored from the worker.
    After that, the delays of the next stochastic gradients will not exceed $R - 1$ during these iterations.
    As soon as some worker finishes calculating a stochastic gradient, it immediately starts computing a new stochastic gradient.

    Using a proof by contradiction, assume that \Cref{alg:ringmasternewstops} will not be able to finish iteration $k + R - 1$ by the time $t$.
    At the same time, by the time $t$, all workers will calculate at least
    \begin{align}
        \label{eq:RQKxmnzvrIUDaroZE}
        \sum_{i=1}^{n} \max\left\{\flr{\frac{t}{\tau_i}} - 1, 0\right\}
    \end{align}
    stochastic gradients with delays $< R$ because $\flr{\frac{t}{\tau_i}}$ is the number of stochastic gradients that worker $i$ can calculate after $t$ seconds.
    We subtract $1$ to account for the fact that one stochastic gradient with a large delay can be ignored.
    Let us take an index
    \begin{align*}
        j^* = \arg\min_{m\in[n]} \left(\left(\sum_{i=1}^m \frac{1}{\tau_i}\right)^{-1} (R + m)\right).
    \end{align*}
    Since $\flr{x} \geq x - 1$ for all $x \geq 0$, we get
    \begin{align*}
        \sum_{i=1}^{n} \max\left\{\flr{\frac{t}{\tau_i}} - 1, 0\right\} 
        &\geq \sum_{i=1}^{j^*} \max\left\{\flr{\frac{t}{\tau_i}} - 1, 0\right\} \geq \sum_{i=1}^{j^*} \left(\flr{\frac{t}{\tau_i}} - 1\right) \geq \sum_{i=1}^{j^*} \frac{t}{\tau_i} - 2 j^* \\
        &= 2 \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) \left(\left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1} (R + j^*)\right) - 2 j^* = 2 R + 2 j^* - 2 j^* \geq R.
    \end{align*}
    % where the last inequality due to the inequality $\flr{x} \geq \frac{x}{2}$ for all $x \geq 1.$
    We can conclude that by the time \eqref{eq:time_R}, the algorithm will calculate $R$ stochastic gradients with delays $< R$ and finish iteration $k + R - 1$, which contradicts the assumption. 

    The proof for \Cref{alg:ringmasternew} is essentially the same.
    In \Cref{alg:ringmasternew}, one stochastic gradient with a large delay for each worker will be ignored, and all other stochastic will be used in the optimization process.
\end{proof}

\section{Proof of Lemma~\ref{lem:time_R_dyn}}
\label{sec:time_R_dyn}

\begin{restate-lemma}{\ref{lem:time_R_dyn}}
    Let the workers' computation times satisfy the \emph{universal computation model}.
    Let $R$ be the delay threshold of \Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}.
    Assume that some iteration starts at time $T_0$.
    Starting from this iteration, the $R$ consecutive iterative updates of \Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops} will be performed before the time
    \begin{equation*} 
        T(R,T_0) \eqdef \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{T_0}^{T} v_i(\tau) d \tau} \geq R\right\}.
    \end{equation*}
\end{restate-lemma}

\begin{proof}
    Let 
    \begin{align*}
        T \eqdef T(R,T_0) = \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{T_0}^{T} v_i(\tau) d \tau} \geq R\right\}.
    \end{align*}
    At the beginning, this proof follows the proof of \Cref{lem:time_R} up to \eqref{eq:RQKxmnzvrIUDaroZE}.
    Here we also use a proof by contradiction and assume that \Cref{alg:ringmasternewstops} will not be able to do $R$ consecutive iterative updates by the time $T$.

    Instead of \eqref{eq:RQKxmnzvrIUDaroZE}, all workers will calculate at least
    \begin{align*}
        N \eqdef \sum_{i=1}^{n} \max\left\{\flr{\int_{T_0}^{T} v_i(\tau) d \tau} - 1, 0\right\} 
    \end{align*}
    stochastic gradients by time $T$ because, due to \eqref{eq:rSIiSfVcmivSKsfzoSA}, $\flr{\int_{T_0}^{T} v_i(\tau) d \tau}$ is the number of stochastic gradients that worker $i$ will calculate in the interval $[T_0, T]$.
    We define $V_i(T) \eqdef \int_{T_0}^{T} v_i(\tau) d \tau$.
    Thus,
    \begin{align*}
        N = \sum_{i=1}^{n} \max\left\{\flr{V_i(T)} - 1, 0\right\} \textnormal{ and } T = \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{V_i(T)}{4}} \geq R\right\}.
    \end{align*}
    Let us additionally define
    \begin{align}
        S \eqdef \left\{i \in [n] \,:\, \frac{V_i(T)}{4} \geq 1\right\}.
        \label{eq:peCcI}
    \end{align} 
    Note that
    \begin{align}
        \label{eq:XwmTgavNaBJOKaRgFMT}
        \sum_{i=1}^{n} \flr{\frac{V_i(T)}{4}} = \sum_{i \in S} \flr{\frac{V_i(T)}{4}},
    \end{align}
    since $\flr{\frac{V_i(T)}{4}} = 0$ for all $i \not\in S$.
    Using simple algebra, we get
    \begin{align*}
        N = \sum_{i=1}^{n} \max\{\flr{V_i(T)} - 1, 0\} &\geq \sum_{i \in S} \max\{\flr{V_i(T)} - 1, 0\} 
        \geq \sum_{i \in S} \flr{V_i(T)} - |S| \geq \sum_{i \in S} V_i(T) - 2 |S|,
    \end{align*}
    where the last inequality due to $\flr{x} \geq x - 1$ for all $x \in \R$.
    Next
    \begin{align*}
        N \overset{\eqref{eq:peCcI}}{\geq} \frac{1}{2} \sum_{i \in S} V_i(T) + \frac{1}{2} \sum_{i \in S} 4 - 2 |S| = \sum_{i \in S} \frac{V_i(T)}{2} \geq \sum_{i \in S} \flr{\frac{V_i(T)}{4}} \overset{\eqref{eq:XwmTgavNaBJOKaRgFMT}}{=} \sum_{i=1}^{n} \flr{\frac{V_i(T)}{4}} \geq R,
    \end{align*}
    where the last inequality due to the definition of $T$.
    As in the proof of \Cref{lem:time_R}, we can conclude that by the time $T = T(R,T_0)$, the algorithm will calculate $R$ stochastic gradients with delays $< R$ and finish iteration $k + R - 1,$ which contradicts the assumption.
\end{proof}

