We adopt the proof strategy from \citet{koloskova2022sharper} and rely on the following two lemmas.

\begin{lemma}[Descent Lemma; Proof in Appendix~\ref{proof:descent}]
    \label{lemma:descent}
    Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, if the stepsize in \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) satisfies $\gamma \le \frac{1}{2L}$, the following inequality holds:
    $$
    \ExpSub{k+1}{f\(x^{k+1}\)} 
    \leq f\(x^{k}\) - \frac{\gamma}{2} \sqnorm{\nabla f\(x^{k}\)} - \frac{\gamma}{4}\sqnorm{\nabla f\(x^{k-\delta^k}\)} + \frac{\gamma L^2}{2}\sqnorm{x^k - x^{k-\delta^k}} + \frac{\gamma^2 L}{2} \sigma^2,
    $$
    where $\ExpSub{k+1}{\cdot}$ represents the expectation conditioned on all randomness up to iteration $k$.
\end{lemma}

\begin{lemma}[Residual Estimation; Proof in Appendix~\ref{proof:residual}]
    \label{lemma:residual}
    Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, the iterates of \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) with stepsize $\gamma \leq \frac{1}{2RL}$ satisfy the following bound:
    $$
    \frac{1}{K+1} \sum_{k=0}^K \E{\sqnorm{x^k - x^{k-\delta^k}}} \leq \frac{1}{2 L^2(K+1)} \sum_{k=0}^K \E{\sqnorm{\nabla f\(x^{k-\delta^k}\)}} + \frac{\gamma}{L} \sigma^2.
    $$
\end{lemma}

With these results, we are now ready to prove \Cref{thm:ringmaster_iteration}.

\begin{proof}[Proof of \Cref{thm:ringmaster_iteration}]
We begin by averaging over $K+1$ iterations and dividing by $\gamma$ in the inequality from \Cref{lemma:descent}:
\begin{align*}
\frac{1}{K+1} \sum_{k=0}^K \( \frac{1}{2} \E{ \sqnorm{\nabla f\(x^k\)}} + \frac{1}{4} \E{ \sqnorm{\nabla f(x^{k-\delta^k})}} \) 
& \leq \frac{\Delta}{\gamma(K+1)} + \frac{\gamma L}{2} \sigma^2 \\ 
&\quad + \frac{1}{K+1} \frac{L^2}{2} \sum_{k=0}^K \E{ \sqnorm{x^k - x^{k-\delta^k}}}.
\end{align*}
Next, applying \Cref{lemma:residual} to the last term, we have:
\begin{align*}
    \frac{1}{K+1} \sum_{k=0}^K \( \frac{1}{2} \E{ \sqnorm{\nabla f\(x^k\)}} + \frac{1}{4} \E{ \sqnorm{\nabla f(x^{k-\delta^k})}} \) 
    & \leq \frac{\Delta}{\gamma(K+1)} + \frac{\gamma L}{2} \sigma^2 \\ 
    &\quad + \frac{1}{4(K+1)} \sum_{k=0}^K \E{\sqnorm{\nabla f\(x^{k-\delta^k}\)}} + \frac{\gamma L}{2}\sigma^2.
\end{align*}
Simplifying further, we obtain:
$$
\frac{1}{K+1} \sum_{k=0}^K \E{ \sqnorm{\nabla f\(x^k\)} } \leq \frac{2\Delta}{\gamma(K+1)} + 2\gamma L \sigma^2.
$$

Now, we choose the stepsize $\gamma$ as:
$$
\gamma = \min \left\{ \frac{1}{2RL}, \frac{\varepsilon}{4L\sigma^2} \right\} \leq \frac{1}{2 R L}.
$$
With this choice of $\gamma$, it remains to choose
$$
K \geq \frac{8 \Delta R L}{\epsilon} + \frac{16 \Delta L \sigma^2}{\epsilon^2}
$$ 
to ensure
$$
\frac{1}{K+1} \sum_{k=0}^{K} \E{\sqnorm{ \nabla f\(x^k\) }} \leq \epsilon.
$$
This completes the proof.

\end{proof}


\subsection{Proof of \Cref{lemma:descent}}
\label{proof:descent}

\begin{restate-lemma}{\ref{lemma:descent}}[Descent Lemma]
    Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, if the stepsize in \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) satisfies $\gamma \le \frac{1}{2L}$, the following inequality holds:
    $$
    \ExpSub{k+1}{f\(x^{k+1}\)} 
    \leq f\(x^{k}\) - \frac{\gamma}{2} \sqnorm{\nabla f\(x^{k}\)} - \frac{\gamma}{4}\sqnorm{\nabla f\(x^{k-\delta^k}\)} + \frac{\gamma L^2}{2}\sqnorm{x^k - x^{k-\delta^k}} + \frac{\gamma^2 L}{2} \sigma^2,
    $$
    where $\ExpSub{k+1}{\cdot}$ represents the expectation conditioned on all randomness up to iteration $k$.
\end{restate-lemma}

% \begin{restate-lemma}{\ref{lemma:descent}}[Descent Lemma]
%     Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, if the stepsize in \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) satisfies $\gamma \le \frac{3}{4L}$, the following inequality holds:
%     $$
%     \ExpSub{k+1}{f\(x^{k+1}\)} 
%     \leq f\(x^{k}\) - \frac{\gamma}{2} \sqnorm{\nabla f\(x^{k}\)} - \frac{\gamma}{8}\sqnorm{\nabla f\(x^{k-\delta^k}\)} + \frac{\gamma L^2}{2}\sqnorm{x^k - x^{k-\delta^k}} + \frac{\gamma^2 L}{2} \sigma^2,
%     $$
%     where $\ExpSub{k+1}{\cdot}$ represents the expectation conditioned on all randomness up to iteration $k$.
% \end{restate-lemma}

\begin{proof}
Assume that we get a stochastic gradient from the worker with index $i_k$ when calculating $x^{k+1}$.
Since the function $f$ is $L$-smooth (Assumption~\ref{ass:lipschitz_constant}), we have \citep{nesterov2018lectures}:
\begin{eqnarray*}
    \ExpSub{k+1}{f\(x^{k+1}\)} 
    &\le& f\(x^{k}\) 
        - \gamma \underbrace{\ExpSub{k+1}{\< \nabla f\(x^{k}\), \nabla f\(x^{k-\delta^k}; \xi^{k-\delta^k}_{i_k}\) \>}}_{=: t_1} 
        \; + \; \frac{L}{2} \gamma^2 \underbrace{\ExpSub{k+1}{\sqnorm{\nabla f\(x^{k-\delta^k}; \xi^{k-\delta^k}_{i_k}\)}}}_{=: t_2}.
\end{eqnarray*}
Using Assumption~\ref{ass:stochastic_variance_bounded}, we estimate the second term as
$$
t_1 
= \< \nabla f\(x^{k}\), \nabla f\(x^{k-\delta^k}\) \> 
= \frac{1}{2} \[\sqnorm{\nabla f\(x^{k}\)} 
    + \sqnorm{\nabla f\(x^{k-\delta^k}\)} 
    - \sqnorm{\nabla f\(x^{k}\) - \nabla f\(x^{k-\delta^k}\)} \].
$$
% Next, for $t_2$, we add and subtract $\nabla f\(x^{k-\delta^k}\)$, then use \Cref{ass:stochastic_variance_bounded} to bound the result:
Using the variance decomposition equality and Assumption~\ref{ass:stochastic_variance_bounded}, we get
\begin{eqnarray*}
t_2 
&=& \ExpSub{k+1}{\sqnorm{\nabla f\(x^{k-\delta^k}; \xi^{k-\delta^k}_{i_k}\) - \nabla f\(x^{k-\delta^k}\)}} 
    + \sqnorm{\nabla f\(x^{k-\delta^k}\)} \\
&\le& \sigma^2 
    + \sqnorm{\nabla f\(x^{k-\delta^k}\)} .
\end{eqnarray*}
Combining the results for $t_1$ and $t_2$, and using $L$-smoothness to bound $\sqnorm{\nabla f\(x^{k}\) - \nabla f\(x^{k-\delta^k}\)}$, we get:
$$
\ExpSub{k+1}{f\(x^{k+1}\)} 
\leq f\(x^{k}\) - \frac{\gamma}{2} \sqnorm{\nabla f\(x^{k}\)} - \frac{\gamma}{2} (1 - \gamma L) \sqnorm{\nabla f\(x^{k-\delta^k}\)} + \frac{\gamma L^2}{2}\sqnorm{x^k - x^{k-\delta^k}} + \frac{\gamma^2 L}{2} \sigma^2.
$$
Finally, applying the condition $\gamma \le \frac{1}{2 L}$ completes the proof.
\end{proof}


\subsection{Proof of \Cref{lemma:residual}}
\label{proof:residual}

\begin{restate-lemma}{\ref{lemma:residual}}[Residual Estimation]
    Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, the iterates of \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) with stepsize $\gamma \leq \frac{1}{2RL}$ satisfy the following bound:
    $$
    \frac{1}{K+1} \sum_{k=0}^K \E{\sqnorm{x^k - x^{k-\delta^k}}} \leq \frac{1}{2 L^2(K+1)} \sum_{k=0}^K \E{\sqnorm{\nabla f\(x^{k-\delta^k}\)}} + \frac{\gamma}{L} \sigma^2.
    $$
\end{restate-lemma}

% \begin{restate-lemma}{\ref{lemma:residual}}[Residual Estimation]
% Under Assumptions \ref{ass:lipschitz_constant} and \ref{ass:stochastic_variance_bounded}, the iterates of \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) with stepsize $\gamma \leq \frac{1}{2RL}$ satisfy the following bound:
% $$
% \frac{1}{K+1} \sum_{k=0}^K \E{\sqnorm{x^k - x^{k-\delta^k}}} \leq \frac{1}{4L^2(K+1)} \sum_{k=0}^K \E{\sqnorm{\nabla f\(x^{k-\delta^k}\)}} + \frac{\gamma}{2L} \sigma^2.
% $$
% \end{restate-lemma}

\begin{proof}
Assume that we get a stochastic gradient from the worker with index $i_k$ when calculating $x^{k+1}$.
We begin by expanding the difference and applying the tower property, Assumption~\ref{ass:stochastic_variance_bounded}, Young's inequality, and Jensen's inequality:
\begin{align*}
\E{ \sqnorm{x^k - x^{k-\delta^k}} } 
& = \E{ \sqnorm{ \sum_{j=k-\delta^k}^{k-1} \gamma \nabla f\(x^{j-\delta_j}; \xi^{j-\delta_j}_{i_j}\) } } \\
& \leq 2 \E{ \sqnorm{ \sum_{j=k-\delta^k}^{k-1} \gamma \nabla f\(x^{j-\delta_j}\) } } + 2 \E{ \sqnorm{ \sum_{j=k-\delta^k}^{k-1} \gamma \left(\nabla f\(x^{j-\delta_j}; \xi^{j-\delta_j}_{i_j}\) - \nabla f\(x^{j-\delta_j}\)\right) } }\\
& \leq 2 \E{ \sqnorm{ \gamma \sum_{j=k-\delta^k}^{k-1}  \nabla f\(x^{j-\delta_j}\) } } + 2 \delta^k \gamma^2 \sigma^2\\
& \leq 2 \delta^k \gamma^2 \sum_{j=k-\delta^k}^{k-1} \E{ \sqnorm{\nabla f\(x^{j-\delta_j}\)}} + 2 \delta^k \gamma^2 \sigma^2.
\end{align*}

Using that $\gamma \leq \frac{1}{2RL}$ and $\delta^k \leq R - 1$ (by the design), we obtain:
\begin{align*}
\E{ \sqnorm{x^k - x^{k-\delta^k}}} 
& \leq \frac{1}{2 L^2 R} \sum_{j=k-\delta^k}^{k-1} \E{ \sqnorm{\nabla f\(x^{j-\delta_j}\)}} + \frac{\gamma}{L} \sigma^2.
\end{align*}

Next, summing over all iterations $k = 0, \dots, K$, we get:
\begin{align*}
\sum_{k=0}^K \E{ \sqnorm{x^k - x^{k-\delta^k}}} 
& \leq \frac{1}{2 L^2 R} \sum_{k=0}^K \sum_{j=k-\delta^k}^{k-1} \E{ \sqnorm{\nabla f\(x^{j-\delta_j}\)} } + \(K+1\) \frac{\gamma}{L} \sigma^2 .
\end{align*}
Observe that each squared norm $\sqnorm{\nabla f\(x^{j-\delta_j}\)}$ in the right-hand sums appears at most $R$ times due to the algorithms' design.
Specifically, $\delta^k \leq R - 1$ for all $k \geq 0$, ensuring no more than $R$ squared norms appear in the sums.
Therefore:
\begin{align*}
\sum_{k=0}^K \E{ \sqnorm{x^k - x^{k-\delta^k}} } & \leq \frac{1}{2 L^2} \sum_{k=0}^K \E{ \sqnorm{\nabla f\(x^{k-\delta^k}\)} } + \(K+1\) \frac{\gamma}{L} \sigma^2.
\end{align*}
Finally, dividing the inequality by $K+1$ completes the proof.
\end{proof}

\section{Proof of Theorem~\ref{thm:optimal_ringmaster_dynamic}}
\label{sec:proof_dyn}

\begin{restate-theorem}{\ref{thm:optimal_ringmaster_dynamic}}
    Let Assumptions \ref{ass:lipschitz_constant}, \ref{ass:lower_bound}, and \ref{ass:stochastic_variance_bounded} hold.
    Let the stepsize in \algname{Ringmaster ASGD} (\Cref{alg:ringmasternew} or \Cref{alg:ringmasternewstops}) be
    $\gamma = \min \left\{ \frac{1}{2RL}, \frac{\varepsilon}{4L\sigma^2} \right\}$, and delay threshold $R = \max\left\{1,\left\lceil \frac{\sigma^2}{\varepsilon} \right\rceil\right\}$.
    Then, under the \emph{universal computation model}, \algname{Ringmaster ASGD} finds an $\varepsilon$--stationary point after at most $T_{\bar{K}}$ seconds, where $\bar{K} \eqdef \left\lceil\frac{48 L \Delta}{\epsilon}\right\rceil$ and $T_{\bar{K}}$ is the $\bar{K}$\textsuperscript{th} element of the following recursively defined sequence:
    \begin{align*}
        T_{K} \eqdef \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{T_{K - 1}}^{T} v_i(\tau) d \tau} \geq R\right\}
    \end{align*}
    for all $K \geq 1$ and $T_{0} = 0$.
\end{restate-theorem}

\begin{proof}
    From \Cref{thm:ringmaster_iteration}, the iteration complexity of \algname{Ringmaster ASGD} is
    \begin{align}
    K = \left\lceil\frac{8 R L \Delta}{\epsilon} + \frac{16 \sigma^2 L \Delta}{\epsilon^2}\right\rceil.
    % \leq \left\lceil\frac{32 \sigma^2 L \Delta}{\epsilon^2}\right\rceil,
    \end{align}
    Without loss of generality, we assume that
    \footnote{Otherwise, using $L$--smoothness, $\norm{\nabla f(x^0)}^2 \leq 2 L \Delta \leq \varepsilon,$ and the initial point is an $\varepsilon$--stationary point}
    $L \Delta > \varepsilon / 2$.
    Thus, $\left\lceil\frac{8 R L \Delta}{\epsilon} + \frac{16 \sigma^2 L \Delta}{\epsilon^2}\right\rceil \leq \frac{16 R L \Delta}{\epsilon} + \frac{32 \sigma^2 L \Delta}{\epsilon^2}$ and
    \begin{align*}
        K \leq R \times \left\lceil\frac{K}{R}\right\rceil = R \times \left\lceil\frac{16 L \Delta}{\epsilon} + \frac{32 \sigma^2 L \Delta}{R \epsilon^2}\right\rceil.
    \end{align*}
    Using the choice of $R,$ we get
    \begin{align*}
        K \leq R \times \left\lceil\frac{48 L \Delta}{\epsilon}\right\rceil.
    \end{align*}
    In total, the algorithms will require $\left\lceil\frac{48 L \Delta}{\epsilon}\right\rceil$ by $R$ consecutive updates of $x^k$ to find an $\varepsilon$--stationary point.
    Let us define $\bar{K} \eqdef \left\lceil\frac{48 L \Delta}{\epsilon}\right\rceil$.
    Using \Cref{lem:time_R_dyn}, we know that \algname{Ringmaster ASGD} requires at most 
    $$
    T_{1} \eqdef T(R,0) = \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{0}^{T} v_i(\tau) d \tau} \geq R\right\}
    $$
    seconds to finish the first $R$ consecutive updates of the iterates.
    Since the algorithms will finish the \emph{first} $R$ consecutive updates after at most $T_{1}$ seconds, they will start the iteration $R + 1$ before time $T_{1}$.
    Thus, using \Cref{lem:time_R_dyn} again, they will require at most 
    $$
    T_{2} \eqdef T(R,T_{1}) = \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{T_{1}}^{T} v_i(\tau) d \tau} \geq R\right\}
    $$
    seconds to finish the first $2 \times R$ consecutive updates.
    Using the same reasoning, they will finish the first $\left\lceil\frac{48 L \Delta}{\epsilon}\right\rceil \times R$ consecutive updates after at most
    $$
    T_{\bar{K}} \eqdef T(R,T_{\bar{K} - 1}) = \min \left\{T \geq 0 : \sum_{i=1}^{n} \flr{\frac{1}{4} \int_{T_{\bar{K} - 1}}^{T} v_i(\tau) d \tau} \geq R\right\}
    $$
    seconds.
\end{proof}

\section{Derivations for the Example from Section~\ref{sec:prel}}
\label{sec:deriv}

Let $\tau_i = \sqrt{i}$ for all $i \in [n],$ then

$$
T_{\textnormal{R}} = \Theta\left(\min\limits_{m \in [n]} \left(\frac{1}{m}\sum\limits_{i=1}^m \frac{1}{\sqrt{i}}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right)\right).
$$

Using 
$$
\sum_{i=1}^m \frac{1}{\sqrt{i}} = \Theta\left(\sqrt{m}\right)
$$ 
for $m \geq 1$, we simplify the term:
$$
\left(\frac{1}{m}\sum\limits_{i=1}^m \frac{1}{\sqrt{i}}\right)^{-1} = \Theta(\sqrt{m}),
$$
$$
    T_{\textnormal{R}} = \Theta \left(\min\limits_{m \in [n]} \sqrt{m} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{m \varepsilon^2}\right) \right) = \Theta \left(\min\limits_{m \in [n]} \left(\frac{L \Delta \sqrt{m}}{\varepsilon} + \frac{\sigma^2 L \Delta}{\sqrt{m} \varepsilon^2}\right)\right).
$$
The minimum is achieved when the two terms are balanced, i.e., at 
$$
m = \min\left\{\left\lceil \frac{\sigma^2}{\varepsilon} \right\rceil, n \right\}.
$$ 
Substituting this value of $m$, we obtain:
$$
T_{\textnormal{R}} = \Theta \left(\max\left[\frac{\sigma L \Delta}{\varepsilon^{3/2}}, \frac{\sigma^2 L \Delta}{\sqrt{n} \varepsilon^2}\right]\right).
$$

We now consider $T_{\textnormal{A}}$:
$$
T_{\textnormal{A}} = \Theta\left(\left(\frac{1}{n} \sum\limits_{i=1}^{n} \frac{1}{\tau_{i}}\right)^{-1} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right).
$$

Using 
$$
\sum_{i=1}^n \frac{1}{\sqrt{i}} = \Theta\left(\sqrt{n}\right)
$$
for $n \geq 1$, we simplify the term:
$$
\left(\frac{1}{n} \sum\limits_{i=1}^n \frac{1}{\sqrt{i}}\right)^{-1} = \Theta\left(\sqrt{n}\right).
$$

Substituting this result into $T_{\textnormal{A}}$, we have:
$$
T_{\textnormal{A}} = \Theta\left(\sqrt{n} \left(\frac{L \Delta}{\varepsilon} + \frac{\sigma^2 L \Delta}{n \varepsilon^2}\right)\right) = \Theta\left(\frac{L \Delta \sqrt{n}}{\varepsilon} + \frac{\sigma^2 L \Delta}{\sqrt{n} \varepsilon^2}\right) = \Theta\left(\max\left[\frac{L \Delta \sqrt{n}}{\varepsilon}, \frac{\sigma^2 L \Delta}{\sqrt{n} \varepsilon^2}\right]\right).
$$

\section{When the Initial Point is an $\varepsilon$--Stationary Point}
\label{sec:l_init}
Under the assumption of $L$--smoothness (Assumption~\ref{ass:lipschitz_constant}), we have:
\begin{align*}
    f(y) \leq f(x) + \inp{\nabla f(x)}{y - x} + \frac{L}{2} \norm{y - x}^2
\end{align*}
for all $x, y \in \R^d$.
Taking $y = x - \frac{1}{L} \nabla f(x),$
\begin{align*}
    f\(x - \frac{1}{L} \nabla f(x)\) \leq f(x) - \frac{1}{2 L} \norm{\nabla f(x)}^2.
\end{align*}
Since $f\(x - \frac{1}{L} \nabla f(x)\) \geq f^{\inf}$ and taking $x = x^0,$ we get
\begin{align*}
    \norm{\nabla f(x^0)}^2 \leq 2 L \Delta.
\end{align*}
Thus, if $2 L \Delta \leq \varepsilon$, then $\norm{\nabla f(x^0)}^2 \leq \varepsilon$.


\section{Experiments} 
\label{sec:experiments}
\algname{Asynchronous SGD} has consistently demonstrated its effectiveness and practicality, achieving strong performance in various applications \citep{recht2011hogwild,lian2018asynchronous,mishchenko2022asynchronous}, along with numerous other studies supporting its utility.
Our main goal of this paper was to refine the method further and establish that it is not only practical but also \emph{theoretically optimal}.

At the same time, \citet{tyurin2024optimal} found out that the previous version of \algname{Asynchronous SGD} has slow convergence when the number of workers is large, and their computation performances are heterogeneous using numerical experiments (see \Cref{fig:n_10000}).

