    \centerline{\includegraphics[width=0.75\textwidth]{Plots/ringmaster_.pdf}}
    \caption{Experiment with $n = 6174$ and $d = 1729$ showing the convergence of \algname{Ringmaster ASGD}, \algname{Delay-Adaptive ASGD}, and \algname{Rennala SGD}.}
    \label{fig:1}
    \end{center}
\end{figure}

\subsection{Neural Network Experiment}

To show that our method also works well for neural networks, we trained a small 20-layer neural network with ReLU activation on the MNIST dataset \citep{lecun1998gradient}.
We used the same number of workers as in the previous experiment ($n = 6174$) and kept the same time distributions.
The results are shown in \Cref{fig:mnist}.

\begin{figure}[ht]
    \begin{center}
    \centerline{\includegraphics[width=0.75\textwidth]{Plots/ring.pdf}}
    \caption{
        We run an experiment on a small 2-layer neural network with ReLU activation on the MNIST dataset, showing that our method, \algname{Ringmaster ASGD}, is more robust and outperforms \algname{Delay-Adaptive ASGD} and \algname{Rennala SGD}.
    }
    \label{fig:mnist}
    \end{center}
\end{figure}

